package com.leetcode.array;

import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;

import static java.util.stream.Collectors.groupingBy;

public class ValidAnagram {

    public static void main(String[] args) {
        String s=""
                , t ="" ;
        Map<String, Long> slist = Arrays.stream(s.split("")).collect(
                groupingBy(e-> e , Collectors.counting())) ;


        Map<String, Long> tlist = Arrays.stream(t.split("")).collect(
                groupingBy(e-> e , Collectors.counting())) ;
        for (Map.Entry<String ,Long> m  :  slist.entrySet()) {
            if(!Objects.equals(m.getValue(), tlist.get(m.getKey())))
            {
                System.out.println("sdsad");
                break;
            }
        }

        //System.out.println(result);

    }

    public int[] shuffle(int[] nums, int n) {
        int[] b = new int[n];
        int[] c = new int[nums.length];
        int j = 0;
        int k =0 ;
        for (int i =(n-1)  ; i< nums.length ;  i++) {
            b[j++] = nums[i] ;
        }
        for (int i = 0 ;  i < n ;i++) {
            c[k++] = nums[i];
        }
        for (j = 0 ;  j < n ;j++) {
            c[k++] = b[j];
        }

        return c;
    }
}
